import 'package:flutter/material.dart';
import 'package:flutter_svg/flutter_svg.dart';

/// One selectable profile picture. Every avatar is an ORIGINAL character-style
/// illustration (a genre archetype: space explorer, ninja, wizard, ...), drawn
/// as embedded SVG so no asset files or pubspec entries are needed.
class AvatarPreset {
  const AvatarPreset(this.id, this.label, this.svg);

  /// Stable id saved on the device. Never rename one.
  final String id;
  final String label;
  final String svg;

  /// Fills its parent (clip it to a circle at the call site).
  Widget build({BoxFit fit = BoxFit.cover}) =>
      SvgPicture.string(svg, fit: fit, width: double.infinity, height: double.infinity);
}

